insert into content_blocks (category_id, type, code, text) values
('communication', 'pedagogical_objective', 'COMM_OBJ_001', 'Adapter son message à son interlocuteur et au contexte de communication (registre, canal, timing).'),
('communication', 'pedagogical_objective', 'COMM_OBJ_002', 'Développer une écoute active et pratiquer la reformulation pour fiabiliser les échanges professionnels.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_003', 'Décoder et maîtriser le langage non-verbal, la voix et la posture en situation professionnelle.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_004', 'Structurer un écrit professionnel clair, concis et adapté au destinataire (email, note, courrier).'),
('communication', 'pedagogical_objective', 'COMM_OBJ_005', 'Rédiger un rapport, un compte-rendu de réunion ou une note de synthèse fidèle et exploitable.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_006', 'Maîtriser les techniques de prise de parole (respiration, ancrage, gestion du trac) pour s''exprimer avec assurance.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_007', 'Construire et délivrer un discours structuré devant un auditoire, avec une accroche et une conclusion percutantes.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_008', 'Concevoir un support de présentation visuel efficace et présenter un pitch percutant en temps limité.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_009', 'Utiliser le storytelling pour construire un récit de marque ou de projet à fort impact.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_010', 'Anticiper une situation de communication de crise et élaborer un plan de gestion associé (cartographie des risques, cellule de crise).'),
('communication', 'pedagogical_objective', 'COMM_OBJ_011', 'Élaborer des éléments de langage et piloter une communication de crise en temps réel face à une situation sensible.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_012', 'Construire une relation avec les journalistes et rédiger un communiqué de presse conforme aux usages du secteur.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_013', 'Préparer et mener une interview média ou une conférence de presse.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_014', 'Construire une stratégie de communication institutionnelle cohérente avec l''image et les valeurs de l''organisation.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_015', 'Concevoir un plan de communication interne et choisir les canaux adaptés à chaque message (intranet, newsletter, affichage, réunions).'),
('communication', 'pedagogical_objective', 'COMM_OBJ_016', 'Adapter sa communication managériale aux situations et aux collaborateurs (directif, participatif, délégatif).'),
('communication', 'pedagogical_objective', 'COMM_OBJ_017', 'Donner un feedback constructif à un collaborateur et développer une posture favorisant la cohésion d''équipe.'),
('communication', 'pedagogical_objective', 'COMM_OBJ_018', 'Identifier les sources d''un conflit relationnel et le désamorcer par l''écoute et la médiation.'),
