('communication', 'R021 - Durée courte : priorisation du tronc commun', 'Sur une durée courte, la formation se concentre sur les fondamentaux et un nombre limité de thèmes.', '{"all": [{"variable": "training_duration", "operator": "less_than_or_equal", "value": 14}]}'::jsonb, '[{"type": "set_variable", "key": "comm_priority_focus", "value": "tronc_commun"}]'::jsonb, 0),
('communication', 'R022 - Durée longue : programme enrichi', 'Une durée longue permet d''élargir le programme à des modules complémentaires (événementiel, interculturel, veille métier).', '{"all": [{"variable": "training_duration", "operator": "greater_than_or_equal", "value": 28}]}'::jsonb, '[{"type": "add_module", "code": "COMM_MODULE_EVENEMENTIEL_INTERCULTUREL"}, {"type": "add_module", "code": "COMM_MODULE_VEILLE_IA"}, {"type": "set_variable", "key": "comm_variant", "value": "programme_enrichi"}]'::jsonb, 10),
('communication', 'R023 - Niveau débutant', 'Priorise l''affichage des blocs fondamentaux pour un public débutant, sans dupliquer de contenu.', '{"all": [{"variable": "entry_level", "operator": "equals", "value": "debutant"}]}'::jsonb, '[{"type": "set_variable", "key": "comm_priority_focus", "value": "fondamentaux"}]'::jsonb, 0),
('communication', 'R024 - Niveau avancé', NULL, '{"all": [{"variable": "entry_level", "operator": "equals", "value": "avance"}]}'::jsonb, '[{"type": "add_content_block", "code": "COMM_OBJ_011"}]'::jsonb, 0),
('communication', 'R025 - Profil manager', NULL, '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "manager"}]}'::jsonb, '[{"type": "add_content_block", "code": "COMM_NEED_004"}]'::jsonb, 0),
('communication', 'R026 - Profil commercial', 'Le public commercial est particulièrement concerné par la prise de parole face client (soutenances, rendez-vous, salons).', '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "commercial"}]}'::jsonb, '[{"type": "add_content_block", "code": "COMM_OBJ_007"}]'::jsonb, 0),
('communication', 'R027 - Secteur santé', 'Le secteur de la santé est particulièrement exposé aux situations de communication sensible (annonce, gestion de plaintes, crise sanitaire).', '{"all": [{"variable": "sector", "operator": "equals", "value": "sante"}]}'::jsonb, '[{"type": "add_content_block", "code": "COMM_NEED_003"}]'::jsonb, 0),
('communication', 'R028 - Secteur public / administration', 'Le secteur public est particulièrement concerné par les enjeux de communication institutionnelle.', '{"all": [{"variable": "sector", "operator": "equals", "value": "public"}]}'::jsonb, '[{"type": "add_content_block", "code": "COMM_OBJ_014"}]'::jsonb, 0),
('communication', 'R029 - Module veille IA activé par la veille', 'Illustration du mécanisme veille → règle : ce module a été ajouté suite à une fiche de veille métiers validée en back-office, indépendamment des thèmes choisis.', '{"all": [{"variable": "admin_flag_veille_ia_communication", "operator": "is_true", "value": true}]}'::jsonb, '[{"type": "add_module", "code": "COMM_MODULE_VEILLE_IA"}]'::jsonb, 5);
insert into content_blocks (category_id, type, code, text) values
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_001', 'Identifier et valider une idée entrepreneuriale à partir d''une analyse de ses atouts, contraintes et opportunités de marché (matrice SWOT).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_002', 'Réaliser une étude de marché structurée (analyse de la demande, de l''offre et de la concurrence directe/indirecte).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_003', 'Construire un Business Model Canvas cohérent et argumenté pour formaliser son modèle économique.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_004', 'Rédiger un business plan complet incluant les volets stratégique, commercial et financier.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_005', 'Élaborer un prévisionnel financier (compte de résultat, plan de trésorerie, bilan prévisionnel) sur 3 ans.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_006', 'Choisir la forme juridique adaptée à son projet (entreprise individuelle, micro-entreprise, EURL, SASU, SARL).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_007', 'Identifier les démarches administratives de création et d''immatriculation de l''entreprise (guichet unique, INPI, CFE).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_008', 'Identifier les différentes sources de financement de la création d''entreprise (prêts bancaires, prêts d''honneur, subventions, love money).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_009', 'Constituer un dossier de financement convaincant à présenter à un partenaire bancaire ou financier.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_010', 'Maîtriser les bases de la comptabilité d''un entrepreneur (facturation, suivi des recettes et des dépenses).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_011', 'Comprendre les régimes fiscaux applicables à l''entrepreneur et choisir le régime le plus adapté à son activité.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_012', 'Anticiper et déclarer la TVA et les cotisations sociales de son activité.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_013', 'Suivre et piloter sa trésorerie pour anticiper les besoins de financement à court terme.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_014', 'Construire et utiliser un tableau de bord d''indicateurs clés (KPI) pour piloter son activité.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_015', 'Définir une stratégie commerciale de lancement adaptée à sa cible, son marché et son positionnement prix.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_016', 'Construire son identité de marque et ses premiers supports de communication.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_017', 'Identifier les leviers de développement et de croissance d''une activité (diversification, nouveaux marchés, digitalisation).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_018', 'Élaborer une stratégie de recherche de fonds auprès d''investisseurs (love money, business angels, financement participatif).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_019', 'Gérer les obligations administratives, sociales et fiscales spécifiques de la micro-entreprise/auto-entreprise (seuils, déclarations URSSAF).'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_020', 'Protéger juridiquement son activité (marque, nom commercial, propriété intellectuelle) et rédiger des CGV conformes.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_021', 'Utiliser des outils numériques de gestion (facturation, devis, CRM) pour professionnaliser son activité.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_022', 'Recruter et intégrer un premier collaborateur ou stagiaire en toute sécurité juridique.'),
('entrepreneuriat_gestion', 'pedagogical_objective', 'ENTR_OBJ_023', 'Développer sa présence commerciale par la prospection et le réseau professionnel pour générer ses premiers clients.'),
('entrepreneuriat_gestion', 'skill', 'ENTR_SKILL_001', 'Élaboration d''une étude de marché et d''un Business Model Canvas.'),
('entrepreneuriat_gestion', 'skill', 'ENTR_SKILL_002', 'Construction d''un prévisionnel financier (compte de résultat, trésorerie, bilan).'),
('entrepreneuriat_gestion', 'skill', 'ENTR_SKILL_003', 'Maîtrise des démarches de création et d''immatriculation d''entreprise.'),
('entrepreneuriat_gestion', 'skill', 'ENTR_SKILL_004', 'Pilotage budgétaire et suivi de trésorerie au moyen d''un tableau de bord.'),
('entrepreneuriat_gestion', 'skill', 'ENTR_SKILL_005', 'Prospection commerciale et développement d''un portefeuille clients.'),
('entrepreneuriat_gestion', 'skill', 'ENTR_SKILL_006', 'Utilisation d''outils numériques de gestion (facturation, devis, CRM).'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_001', 'Quel est votre projet entrepreneurial ? Décrivez-le en quelques lignes.'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_002', 'Quelle est votre situation professionnelle actuelle ? (Salarié·e / Demandeur d''emploi / Étudiant / Déjà entrepreneur)'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_003', 'Avez-vous déjà une idée précise d''activité ou êtes-vous encore en phase de réflexion ?'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_004', 'Quel est votre niveau de connaissance en gestion et comptabilité ? (Débutant / Intermédiaire / Avancé)'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_005', 'Avez-vous déjà rédigé un business plan ou un prévisionnel financier ?'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_006', 'Quel statut juridique envisagez-vous pour votre future entreprise, si vous en avez déjà une idée ?'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_007', 'Disposez-vous d''un apport personnel ou de moyens de financement déjà identifiés ?'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_008', 'Quels sont vos objectifs concrets à l''issue de la formation ? (Créer mon entreprise / Structurer mon projet / Trouver des financements / Autre)'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_009', 'Quelle modalité préférez-vous et quelles sont vos disponibilités ? (Présentiel / Distanciel / Hybride)'),
('entrepreneuriat_gestion', 'positioning_question', 'ENTR_POS_010', 'Avez-vous des besoins spécifiques (santé, handicap) à signaler ?'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_001', 'Quiz final Entrepreneuriat/Gestion en ligne (QCM), seuil de réussite : 70 %.'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_002', 'La formation a-t-elle répondu à vos attentes ? (Oui / Partiellement / Non)'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_003', 'Les objectifs pédagogiques étaient-ils clairs et ont-ils été atteints ?'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_004', 'Le formateur a-t-il su s''adapter à votre projet et à votre niveau ?'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_005', 'Quels points amélioreriez-vous ?'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_006', 'Présentation orale du projet entrepreneurial (pitch de 10 minutes) devant le formateur, évaluée sur grille critériée.'),
('entrepreneuriat_gestion', 'evaluation_question', 'ENTR_EVAL_007', 'Étude de cas : analyse d''un prévisionnel financier fourni et identification des erreurs ou incohérences.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_001', 'Réaliser le diagnostic SWOT (forces/faiblesses/opportunités/menaces) de son idée de projet.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_002', 'Mener une étude de marché terrain (interviews, questionnaire en ligne) et en synthétiser les résultats.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_003', 'Compléter un Business Model Canvas à partir de son propre projet entrepreneurial.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_004', 'Rédiger l''executive summary et les parties clés d''un business plan.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_005', 'Élaborer un compte de résultat prévisionnel et un plan de trésorerie sur 12 mois.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_006', 'Comparer les statuts juridiques (EI, micro-entreprise, EURL, SASU) à l''aide d''un tableau comparatif appliqué à son projet.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_007', 'Simuler les démarches d''immatriculation sur le guichet unique des formalités des entreprises.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_008', 'Construire un plan de financement et identifier les dispositifs d''aide mobilisables (ACRE, prêt d''honneur, subventions régionales).'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_009', 'Tenir un livre de recettes-dépenses et émettre une facture conforme à la réglementation.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_010', 'Simuler le calcul de ses cotisations sociales et de sa TVA selon le régime fiscal choisi.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_011', 'Construire un tableau de bord de pilotage avec 5 indicateurs clés adaptés à son activité.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_012', 'Élaborer un plan d''actions commerciales de lancement (cibles, canaux, calendrier, budget).'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_013', 'Créer sa charte graphique et un support de communication (flyer, page réseau social) pour son projet.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_014', 'Rédiger des CGV types et identifier les démarches de protection de sa marque auprès de l''INPI.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_015', 'Simuler un entretien avec un partenaire bancaire ou un investisseur pour présenter son dossier de financement.'),
('entrepreneuriat_gestion', 'exercise', 'ENTR_EX_016', 'Rédiger une offre de poste/stage et préparer la trame d''un entretien de recrutement pour un premier collaborateur.'),
('entrepreneuriat_gestion', 'method', 'ENTR_METHOD_001', 'Alternance d''apports théoriques, études de cas réels et travail appliqué sur le projet personnel de chaque apprenant.'),
('entrepreneuriat_gestion', 'method', 'ENTR_METHOD_002', 'Supports variés : présentations interactives, modèles téléchargeables (BMC, prévisionnel, business plan), quiz, études de cas.'),
('entrepreneuriat_gestion', 'method', 'ENTR_METHOD_003', 'Évaluations formatives en cours de formation (quiz, exercices pratiques appliqués au projet).'),
('entrepreneuriat_gestion', 'method', 'ENTR_METHOD_004', 'Évaluation sommative en fin de parcours (pitch du projet, dossier de projet, test de connaissances).'),
('entrepreneuriat_gestion', 'method', 'ENTR_METHOD_005', 'Positionnement à l''entrée via entretien diagnostic sur le projet et le niveau de connaissance en gestion.'),
('entrepreneuriat_gestion', 'method', 'ENTR_METHOD_006', 'Modalité hybride combinant présentiel et classe virtuelle avec ateliers collaboratifs à distance.'),
('entrepreneuriat_gestion', 'need_example', 'ENTR_NEED_001', 'Transformer une idée en projet structuré et validé avant de se lancer.'),
('entrepreneuriat_gestion', 'need_example', 'ENTR_NEED_002', 'Sécuriser son financement pour lancer son activité (prêt bancaire, subventions, love money).'),
('entrepreneuriat_gestion', 'need_example', 'ENTR_NEED_003', 'Comprendre les obligations comptables et fiscales pour gérer son entreprise en autonomie.'),
('entrepreneuriat_gestion', 'need_example', 'ENTR_NEED_004', 'Structurer sa stratégie commerciale pour obtenir ses premiers clients rapidement après le lancement.'),
('entrepreneuriat_gestion', 'need_example', 'ENTR_NEED_005', 'Passer du statut de micro-entrepreneur à une société (SASU/EURL) en anticipant la croissance de l''activité.'),
('entrepreneuriat_gestion', 'need_example', 'ENTR_NEED_006', 'Sécuriser juridiquement son activité (marque, CGV) avant le lancement commercial.');
