('entrepreneuriat_gestion', 'R007 - Financement de la création', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "financement_creation"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_008"}, {"type": "add_content_block", "code": "ENTR_OBJ_009"}, {"type": "add_content_block", "code": "ENTR_EX_008"}, {"type": "add_content_block", "code": "ENTR_EX_015"}, {"type": "add_content_block", "code": "ENTR_NEED_002"}, {"type": "add_module", "code": "ENTR_MODULE_FINANCEMENT"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R008 - Gestion financière et comptabilité de base', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "gestion_financiere_comptabilite"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_010"}, {"type": "add_content_block", "code": "ENTR_EX_009"}, {"type": "add_content_block", "code": "ENTR_NEED_003"}, {"type": "add_module", "code": "ENTR_MODULE_COMPTA_FISCALITE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R009 - Fiscalité de l''entrepreneur', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "fiscalite_entrepreneur"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_011"}, {"type": "add_content_block", "code": "ENTR_OBJ_012"}, {"type": "add_content_block", "code": "ENTR_EX_010"}, {"type": "add_module", "code": "ENTR_MODULE_COMPTA_FISCALITE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R010 - Gestion de la trésorerie', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "gestion_tresorerie"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_013"}, {"type": "add_module", "code": "ENTR_MODULE_TRESORERIE_KPI"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R011 - Pilotage d''activité et KPI', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "pilotage_kpi"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_014"}, {"type": "add_content_block", "code": "ENTR_SKILL_004"}, {"type": "add_content_block", "code": "ENTR_EX_011"}, {"type": "add_module", "code": "ENTR_MODULE_TRESORERIE_KPI"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R012 - Stratégie commerciale de lancement', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "strategie_commerciale_lancement"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_015"}, {"type": "add_content_block", "code": "ENTR_OBJ_023"}, {"type": "add_content_block", "code": "ENTR_SKILL_005"}, {"type": "add_content_block", "code": "ENTR_EX_012"}, {"type": "add_content_block", "code": "ENTR_NEED_004"}, {"type": "add_module", "code": "ENTR_MODULE_STRATEGIE_COMMERCIALE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R013 - Communication et image de marque', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "communication_marque"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_016"}, {"type": "add_content_block", "code": "ENTR_EX_013"}, {"type": "add_module", "code": "ENTR_MODULE_STRATEGIE_COMMERCIALE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R014 - Développement et croissance de l''activité', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "developpement_croissance"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_017"}, {"type": "add_content_block", "code": "ENTR_NEED_005"}, {"type": "add_module", "code": "ENTR_MODULE_DEVELOPPEMENT_CROISSANCE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R015 - Levée de fonds', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "levee_fonds"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_018"}, {"type": "add_module", "code": "ENTR_MODULE_LEVEE_FONDS"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R016 - Gestion administrative de la micro-entreprise', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "gestion_admin_microentreprise"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_019"}, {"type": "add_module", "code": "ENTR_MODULE_MICROENTREPRISE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R017 - Protection juridique de l''activité', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "protection_juridique"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_020"}, {"type": "add_content_block", "code": "ENTR_EX_014"}, {"type": "add_content_block", "code": "ENTR_NEED_006"}, {"type": "add_module", "code": "ENTR_MODULE_PROTECTION_JURIDIQUE"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R018 - Outils numériques de gestion', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "outils_numeriques_gestion"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_021"}, {"type": "add_content_block", "code": "ENTR_SKILL_006"}, {"type": "add_module", "code": "ENTR_MODULE_OUTILS_RECRUTEMENT"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R019 - Gestion des premiers recrutements', NULL, '{"all": [{"variable": "entr_themes", "operator": "contains", "value": "recrutement_entrepreneur"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_022"}, {"type": "add_content_block", "code": "ENTR_EX_016"}, {"type": "add_module", "code": "ENTR_MODULE_OUTILS_RECRUTEMENT"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R020 - Variante durée courte (7-14h) : focus socle projet', 'Pour une durée courte, priorise les modules fondamentaux (idéation, étude de marché, BMC/business plan) et retire les modules avancés de développement.', '{"all": [{"variable": "training_duration", "operator": "less_than_or_equal", "value": 14}]}'::jsonb, '[{"type": "set_variable", "key": "entr_priority_focus", "value": "socle_projet"}, {"type": "remove_module", "code": "ENTR_MODULE_LEVEE_FONDS"}, {"type": "remove_module", "code": "ENTR_MODULE_DEVELOPPEMENT_CROISSANCE"}]'::jsonb, 10),
('entrepreneuriat_gestion', 'R021 - Variante durée longue (>=35h) : parcours complet création + gestion', 'Pour une durée longue, couverture complète du parcours de la création à la gestion et au développement de l''activité.', '{"all": [{"variable": "training_duration", "operator": "greater_than_or_equal", "value": 35}]}'::jsonb, '[{"type": "add_module", "code": "ENTR_MODULE_IDEATION_ETUDE"}, {"type": "add_module", "code": "ENTR_MODULE_BMC_BP"}, {"type": "add_module", "code": "ENTR_MODULE_STATUT_JURIDIQUE"}, {"type": "add_module", "code": "ENTR_MODULE_FINANCEMENT"}, {"type": "add_module", "code": "ENTR_MODULE_COMPTA_FISCALITE"}, {"type": "add_module", "code": "ENTR_MODULE_TRESORERIE_KPI"}, {"type": "add_module", "code": "ENTR_MODULE_STRATEGIE_COMMERCIALE"}, {"type": "set_variable", "key": "entr_variant", "value": "parcours_complet"}]'::jsonb, 10),
('entrepreneuriat_gestion', 'R022 - Public demandeurs d''emploi en création d''activité', 'Priorise le montage financier et les aides à la création (ACRE, dispositifs Pôle emploi) pour ce public.', '{"all": [{"variable": "public_type", "operator": "in", "value": ["demandeurs_emploi", "demandeur_emploi"]}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_008"}, {"type": "add_content_block", "code": "ENTR_EX_008"}, {"type": "set_variable", "key": "entr_priority_focus", "value": "financement_aides"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R023 - Public micro-entrepreneurs déjà en activité', 'Priorise la gestion administrative de la micro-entreprise et le pilotage plutôt que la phase d''idéation, déjà dépassée pour ce public.', '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "micro_entrepreneur_en_activite"}]}'::jsonb, '[{"type": "add_module", "code": "ENTR_MODULE_MICROENTREPRISE"}, {"type": "add_module", "code": "ENTR_MODULE_TRESORERIE_KPI"}, {"type": "set_variable", "key": "entr_priority_focus", "value": "pilotage_activite_existante"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R024 - Niveau débutant en gestion', 'Marque la priorité d''affichage sur les fondamentaux comptables et juridiques déjà ajoutés par les autres règles, sans dupliquer de contenu.', '{"all": [{"variable": "entry_level", "operator": "equals", "value": "debutant"}]}'::jsonb, '[{"type": "set_variable", "key": "entr_priority_focus", "value": "fondamentaux_gestion"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R025 - Niveau avancé en gestion', 'Pour un public déjà expérimenté, ajoute un objectif complémentaire sur la levée de fonds et la croissance.', '{"all": [{"variable": "entry_level", "operator": "equals", "value": "avance"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_018"}, {"type": "add_content_block", "code": "ENTR_OBJ_017"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R026 - Modalité hybride', NULL, '{"all": [{"variable": "training_method", "operator": "equals", "value": "hybride"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_METHOD_006"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R027 - Secteur artisanat/métiers de bouche', 'Adapte l''exemple de business plan et le module financement à un projet artisanal (investissement matériel, local commercial).', '{"all": [{"variable": "sector", "operator": "equals", "value": "artisanat"}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_EX_008"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R028 - Projet en société (hors micro-entreprise) : accent sur la levée de fonds et le recrutement', 'Un projet visant une société (EURL/SASU/SARL) mobilise davantage les problématiques de financement structuré, de recrutement et de croissance que la micro-entreprise.', '{"all": [{"variable": "entr_statut_envisage", "operator": "in", "value": ["eurl", "sasu", "sarl"]}]}'::jsonb, '[{"type": "add_module", "code": "ENTR_MODULE_LEVEE_FONDS"}, {"type": "add_module", "code": "ENTR_MODULE_OUTILS_RECRUTEMENT"}]'::jsonb, 0),
('entrepreneuriat_gestion', 'R029 - Module veille : dispositifs de financement activé par la veille métiers', 'Illustration du mécanisme veille -> règle : ce contenu a été ajouté suite à une fiche de veille sur les dispositifs de financement, validée en back-office, indépendamment des thèmes choisis.', '{"all": [{"variable": "admin_flag_veille_financement", "operator": "is_true", "value": true}]}'::jsonb, '[{"type": "add_content_block", "code": "ENTR_OBJ_008"}]'::jsonb, 5),
('entrepreneuriat_gestion', 'R030 - Profil reconversion professionnelle', 'Priorise l''accompagnement au montage global du projet (idéation, business plan, financement) pour un public en reconversion.', '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "reconversion_professionnelle"}]}'::jsonb, '[{"type": "set_variable", "key": "entr_priority_focus", "value": "montage_projet_global"}]'::jsonb, 0);
insert into content_blocks (category_id, type, code, text) values
('langues', 'pedagogical_objective', 'LANG_OBJ_001', 'Communiquer avec aisance en anglais professionnel (ou dans la langue cible) dans les situations de travail courantes : réunions, emails, appels téléphoniques.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_002', 'Comprendre et utiliser les structures grammaticales fondamentales de la langue cible à l''oral comme à l''écrit.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_003', 'Enrichir son vocabulaire général pour gagner en autonomie dans des échanges du quotidien.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_004', 'Acquérir et mobiliser le vocabulaire spécifique à son secteur d''activité ou à son métier.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_005', 'Se préparer efficacement à une certification en langue (TOEIC, TOEFL, Linguaskill, Bright Language).'),
('langues', 'pedagogical_objective', 'LANG_OBJ_006', 'Maîtriser les codes et le vocabulaire de l''anglais des affaires (finance, corporate, contrats, présentations).'),
('langues', 'pedagogical_objective', 'LANG_OBJ_007', 'Conduire une négociation commerciale ou contractuelle en langue étrangère.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_008', 'Rédiger des emails, comptes rendus et rapports professionnels clairs, structurés et adaptés au destinataire.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_009', 'Accueillir, renseigner et accompagner une clientèle internationale dans le secteur du tourisme et de l''hôtellerie.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_010', 'Maîtriser le vocabulaire technique et les documents spécifiques à son secteur (normes, fiches techniques, notices, manuels).'),
('langues', 'pedagogical_objective', 'LANG_OBJ_011', 'Gagner en aisance et en spontanéité à l''oral dans des échanges informels et professionnels.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_012', 'Améliorer sa prononciation et son intelligibilité à l''oral grâce à un travail ciblé de phonétique.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_013', 'Préparer et délivrer une prise de parole en public ou un pitch structuré en langue étrangère.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_014', 'Participer activement à des réunions et des conférences téléphoniques ou visio en langue étrangère (prise de parole, reformulation, compte rendu).'),
('langues', 'pedagogical_objective', 'LANG_OBJ_015', 'Argumenter et vendre un produit ou un service en langue étrangère face à un client ou un prospect.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_016', 'Se préparer à un entretien d''embauche ou un entretien professionnel conduit en langue étrangère.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_017', 'Comprendre un discours oral (conversation, présentation, média) prononcé à vitesse normale, y compris avec des accents variés.'),
('langues', 'pedagogical_objective', 'LANG_OBJ_018', 'Comprendre les codes culturels et les usages professionnels du pays de la langue cible pour adapter sa communication.'),
('langues', 'skill', 'LANG_SKILL_001', 'Expression orale en continu et en interaction en langue étrangère.'),
('langues', 'skill', 'LANG_SKILL_002', 'Compréhension orale de discours authentiques (locuteurs natifs, accents variés).'),
('langues', 'skill', 'LANG_SKILL_003', 'Rédaction professionnelle en langue étrangère (emails, comptes rendus, rapports).'),
('langues', 'skill', 'LANG_SKILL_004', 'Négociation et argumentation commerciale en langue étrangère.'),
('langues', 'skill', 'LANG_SKILL_005', 'Prise de parole en public et construction d''un pitch en langue étrangère.'),
('langues', 'skill', 'LANG_SKILL_006', 'Conduite de réunions et d''appels professionnels en langue étrangère.'),
('langues', 'positioning_question', 'LANG_POS_001', 'Quelle formation souhaitez-vous suivre ? (langue visée et objectif principal)'),
('langues', 'positioning_question', 'LANG_POS_002', 'Quelle est votre situation professionnelle actuelle ? (Salarié·e / Entrepreneur / Demandeur d''emploi / Particulier)'),
('langues', 'positioning_question', 'LANG_POS_003', 'Quel est votre secteur d''activité ?'),
('langues', 'positioning_question', 'LANG_POS_004', 'Quel est votre niveau actuel dans la langue cible ? (A1 à C2, selon le Cadre européen commun de référence)'),
('langues', 'positioning_question', 'LANG_POS_005', 'Quelles sont vos attentes ? (Développer des compétences / Obtenir une certification / Autre)'),
('langues', 'positioning_question', 'LANG_POS_006', 'Dans quelles situations utilisez-vous ou utiliserez-vous la langue cible au quotidien ?'),
('langues', 'positioning_question', 'LANG_POS_007', 'Quelle modalité préférez-vous ? (Présentiel / Distanciel / Hybride)'),
('langues', 'positioning_question', 'LANG_POS_008', 'Avez-vous des besoins spécifiques (santé, handicap) à signaler ?'),
('langues', 'positioning_question', 'LANG_POS_009', 'Test de positionnement initial écrit et oral pour évaluer le niveau de départ (grille CECRL).'),
('langues', 'positioning_question', 'LANG_POS_010', 'Visez-vous une certification particulière ? (TOEIC / TOEFL / Linguaskill / Bright Language / aucune)'),
('langues', 'evaluation_question', 'LANG_EVAL_001', 'Test de positionnement / certification blanche en ligne, avec grille de correction CECRL.'),
('langues', 'evaluation_question', 'LANG_EVAL_002', 'La formation a-t-elle répondu à vos attentes ? (Oui / Partiellement / Non)'),
('langues', 'evaluation_question', 'LANG_EVAL_003', 'Les objectifs pédagogiques étaient-ils clairs ?'),
('langues', 'evaluation_question', 'LANG_EVAL_004', 'Le formateur a-t-il su s''adapter à votre niveau ?'),
('langues', 'evaluation_question', 'LANG_EVAL_005', 'Quels points amélioreriez-vous ?'),
('langues', 'evaluation_question', 'LANG_EVAL_006', 'Mise en situation orale évaluée par le formateur (jeu de rôle, entretien simulé).'),
('langues', 'evaluation_question', 'LANG_EVAL_007', 'Épreuve écrite finale (rédaction d''un email ou d''un rapport professionnel) évaluée selon une grille de critères.'),
('langues', 'evaluation_question', 'LANG_EVAL_008', 'Simulation d''examen blanc dans les conditions de la certification visée (TOEIC / TOEFL / Linguaskill / Bright Language).'),
('langues', 'exercise', 'LANG_EX_001', 'Jeu de rôle : se présenter et présenter son poste ou son entreprise en langue étrangère.'),
('langues', 'exercise', 'LANG_EX_002', 'Atelier de compréhension orale à partir d''extraits audio/vidéo authentiques (actualité, interviews).'),
('langues', 'exercise', 'LANG_EX_003', 'Exercices de grammaire ciblés et correction collective en groupe.'),
('langues', 'exercise', 'LANG_EX_004', 'Constitution d''un lexique métier personnalisé à partir de documents professionnels de l''apprenant.'),
('langues', 'exercise', 'LANG_EX_005', 'Entraînement chronométré sur des épreuves types de certification (TOEIC / TOEFL / Linguaskill / Bright Language).'),
('langues', 'exercise', 'LANG_EX_006', 'Étude de cas : lecture et analyse d''un rapport financier ou d''un contrat en anglais des affaires.'),
('langues', 'exercise', 'LANG_EX_007', 'Simulation de négociation commerciale en binôme, avec grille d''évaluation.'),
('langues', 'exercise', 'LANG_EX_008', 'Rédaction d''un email professionnel à partir d''une mise en situation (réclamation, relance, proposition).'),
('langues', 'exercise', 'LANG_EX_009', 'Simulation d''accueil et de renseignement d''un client international (mise en situation hôtellerie / tourisme).'),
('langues', 'exercise', 'LANG_EX_010', 'Traduction et présentation orale d''une fiche technique ou d''une notice sectorielle.'),
('langues', 'exercise', 'LANG_EX_011', 'Atelier conversation libre en petit groupe sur des sujets d''actualité ou professionnels.'),
('langues', 'exercise', 'LANG_EX_012', 'Exercices de phonétique et de répétition (paires minimales, intonation, accentuation).'),
('langues', 'exercise', 'LANG_EX_013', 'Préparation et présentation d''un pitch de 3 minutes devant le groupe, avec feedback filmé.'),
('langues', 'exercise', 'LANG_EX_014', 'Simulation de réunion ou de conférence téléphonique en langue étrangère (prise de parole, reformulation, compte rendu).'),
('langues', 'exercise', 'LANG_EX_015', 'Jeu de rôle vente / argumentation face à un client mécontent ou hésitant.'),
('langues', 'exercise', 'LANG_EX_016', 'Étude de documents culturels (usages professionnels, étiquette des affaires) et mise en situation interculturelle.'),
('langues', 'exercise', 'LANG_EX_017', 'Simulation d''entretien d''embauche en langue étrangère, avec débriefing individualisé.'),
('langues', 'method', 'LANG_METHOD_001', 'Alternance d''apports linguistiques, de mises en situation orales et d''ateliers pratiques.'),
('langues', 'method', 'LANG_METHOD_002', 'Supports variés : documents authentiques audio/vidéo, articles de presse, extraits professionnels, exercices interactifs.'),
('langues', 'method', 'LANG_METHOD_003', 'Évaluations formatives régulières (quiz, mises en situation, corrections individualisées).'),
('langues', 'method', 'LANG_METHOD_004', 'Évaluation sommative en fin de parcours (test final, mise en situation notée ou examen blanc).'),
('langues', 'method', 'LANG_METHOD_005', 'Positionnement à l''entrée via un test écrit et oral selon le Cadre européen commun de référence pour les langues (CECRL).'),
('langues', 'method', 'LANG_METHOD_006', 'Modalité hybride combinant présentiel et classe virtuelle, avec plateforme d''e-learning et suivi individualisé.'),
('langues', 'method', 'LANG_METHOD_007', 'Modalité 100 % distancielle avec plateforme de visioconférence et suivi individualisé en ligne.'),
('langues', 'need_example', 'LANG_NEED_001', 'Gagner en confiance pour prendre la parole en réunion internationale.'),
('langues', 'need_example', 'LANG_NEED_002', 'Réussir une certification en langue exigée par l''employeur ou dans le cadre d''un projet de mobilité professionnelle.'),
('langues', 'need_example', 'LANG_NEED_003', 'Être capable de rédiger des emails professionnels sans erreurs récurrentes.'),
('langues', 'need_example', 'LANG_NEED_004', 'Développer son activité à l''international et négocier avec des clients ou partenaires étrangers.');
insert into modules (category_id, code, title, default_duration_hours, linked_objective_codes, source) values
('langues', 'LANG_MODULE_FONDAMENTAUX', 'Consolidation des fondamentaux : grammaire, vocabulaire général et compréhension orale', 7, ARRAY['LANG_OBJ_002','LANG_OBJ_003','LANG_OBJ_017']::text[], NULL),
('langues', 'LANG_MODULE_ORAL_AISANCE', 'Développer son aisance à l''oral : conversation et phonétique', 7, ARRAY['LANG_OBJ_011','LANG_OBJ_012']::text[], NULL),
('langues', 'LANG_MODULE_PRO_QUOTIDIEN', 'Anglais professionnel au quotidien : réunions, emails et communication écrite', 7, ARRAY['LANG_OBJ_001','LANG_OBJ_008','LANG_OBJ_014']::text[], NULL),
('langues', 'LANG_MODULE_AFFAIRES_NEGO', 'Anglais des affaires, négociation et argumentation commerciale', 7, ARRAY['LANG_OBJ_006','LANG_OBJ_007','LANG_OBJ_015']::text[], NULL),
('langues', 'LANG_MODULE_METIER_TECHNIQUE', 'Vocabulaire métier et anglais technique sectoriel', 7, ARRAY['LANG_OBJ_004','LANG_OBJ_010']::text[], NULL),
('langues', 'LANG_MODULE_CERTIFICATION', 'Préparation intensive à la certification en langue (TOEIC / TOEFL / Linguaskill / Bright Language)', 7, ARRAY['LANG_OBJ_005']::text[], NULL),
