('langues', 'R025 - Secteur tourisme', 'Remplace un exercice générique par un cas pratique sectoriel tourisme/hôtellerie.', '{"all": [{"variable": "sector", "operator": "equals", "value": "tourisme"}]}'::jsonb, '[{"type": "add_content_block", "code": "LANG_EX_009"}, {"type": "add_module", "code": "LANG_MODULE_TOURISME_HOTELLERIE"}]'::jsonb, 0),
