('langues', 'R029 - Parcours complet (durée longue ≥ 28h)', 'Durée longue : le parcours peut couvrir à la fois la préparation certification et l''immersion culturelle.', '{"all": [{"variable": "training_duration", "operator": "greater_than_or_equal", "value": 28}]}'::jsonb, '[{"type": "add_module", "code": "LANG_MODULE_CERTIFICATION"}, {"type": "add_module", "code": "LANG_MODULE_IMMERSION_CULTURELLE"}, {"type": "set_variable", "key": "lang_variant_duree", "value": "complet"}]'::jsonb, 10);
insert into content_blocks (category_id, type, code, text) values
('management', 'pedagogical_objective', 'MGMT_OBJ_001', 'Comprendre les fondamentaux du rôle de manager et les différents styles de leadership (directif, participatif, délégatif, persuasif).'),
('management', 'pedagogical_objective', 'MGMT_OBJ_002', 'Identifier son propre style de leadership et l''adapter aux situations et aux collaborateurs.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_003', 'Développer sa posture de leader pour mobiliser et fédérer une équipe autour d''objectifs communs.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_004', 'Savoir déléguer efficacement une mission en fonction du niveau d''autonomie du collaborateur.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_005', 'Utiliser des outils de suivi de délégation pour sécuriser les missions confiées et prévenir la sur-sollicitation du manager.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_006', 'Identifier les sources et les typologies de conflits au sein d''une équipe.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_007', 'Mettre en œuvre une méthode de résolution de conflit (écoute active, médiation, recherche de solution).'),
('management', 'pedagogical_objective', 'MGMT_OBJ_008', 'Adapter sa communication managériale à chaque interlocuteur et à chaque situation (annonce, recadrage, négociation interne).'),
('management', 'pedagogical_objective', 'MGMT_OBJ_009', 'Accompagner une équipe dans un contexte de changement organisationnel (réorganisation, nouvel outil, fusion).'),
('management', 'pedagogical_objective', 'MGMT_OBJ_010', 'Préparer et conduire un entretien annuel d''évaluation structurant et objectivé.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_011', 'Préparer et conduire un entretien professionnel conforme aux obligations légales.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_012', 'Fixer des objectifs SMART individuels et collectifs et les décliner en plan d''action.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_013', 'Suivre et évaluer la performance individuelle et collective d''une équipe à l''aide d''indicateurs adaptés.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_014', 'Identifier les leviers de motivation individuels et collectifs et les mobiliser au quotidien.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_015', 'Développer une culture du feedback régulier et constructif au sein de l''équipe.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_016', 'Manager une équipe à distance ou en mode hybride en maintenant cohésion et performance.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_017', 'Prévenir et gérer le stress au sein de l''équipe (charge de travail, signaux d''alerte, ressources internes).'),
('management', 'pedagogical_objective', 'MGMT_OBJ_018', 'Réussir l''intégration d''un nouveau collaborateur en construisant un parcours d''onboarding managérial structuré.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_019', 'Manager en mode transversal, sans lien hiérarchique direct, en s''appuyant sur l''influence et la coopération.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_020', 'Construire et animer une dynamique de cohésion d''équipe (team building) adaptée au contexte de l''organisation.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_021', 'Prendre des décisions managériales dans un contexte d''incertitude ou d''urgence en arbitrant entre les options disponibles.'),
('management', 'pedagogical_objective', 'MGMT_OBJ_022', 'Prioriser ses tâches et organiser son temps de manager pour dégager de la disponibilité managériale au service de l''équipe.'),
('management', 'skill', 'MGMT_SKILL_001', 'Adaptation du style de management aux situations et aux collaborateurs.'),
('management', 'skill', 'MGMT_SKILL_002', 'Délégation efficace et suivi de mission.'),
('management', 'skill', 'MGMT_SKILL_003', 'Gestion et résolution de conflits en équipe.'),
('management', 'skill', 'MGMT_SKILL_004', 'Conduite d''entretiens managériaux (annuel, professionnel, recadrage).'),
('management', 'skill', 'MGMT_SKILL_005', 'Animation de réunion et de dynamique d''équipe.'),
('management', 'skill', 'MGMT_SKILL_006', 'Pilotage de la performance et fixation d''objectifs SMART.'),
('management', 'skill', 'MGMT_SKILL_007', 'Management à distance et usage des outils collaboratifs.'),
('management', 'positioning_question', 'MGMT_POS_001', 'Quelle formation souhaitez-vous suivre ?'),
('management', 'positioning_question', 'MGMT_POS_002', 'Quelle est votre situation professionnelle actuelle ? (Salarié·e / Entrepreneur / Demandeur d''emploi / Particulier)'),
('management', 'positioning_question', 'MGMT_POS_003', 'Occupez-vous déjà un poste de management ou vous préparez-vous à le devenir ?'),
('management', 'positioning_question', 'MGMT_POS_004', 'Quelle est la taille de l''équipe que vous encadrez ou encadrerez ?'),
('management', 'positioning_question', 'MGMT_POS_005', 'Quel est votre niveau initial en management ? (Débutant / Intermédiaire / Confirmé)'),
('management', 'positioning_question', 'MGMT_POS_006', 'Quelles sont vos attentes ? (Développer des compétences / Obtenir une certification / Autre)'),
('management', 'positioning_question', 'MGMT_POS_007', 'Quelles difficultés managériales rencontrez-vous actuellement ?'),
('management', 'positioning_question', 'MGMT_POS_008', 'Quelle modalité préférez-vous ? (Présentiel / Distanciel / Hybride)'),
('management', 'positioning_question', 'MGMT_POS_009', 'Avez-vous des besoins spécifiques (santé, handicap) à signaler ?'),
('management', 'evaluation_question', 'MGMT_EVAL_001', 'Quiz final Management en ligne (QCM), seuil de réussite : 70 %.'),
('management', 'evaluation_question', 'MGMT_EVAL_002', 'La formation a-t-elle répondu à vos attentes ? (Oui / Partiellement / Non)'),
('management', 'evaluation_question', 'MGMT_EVAL_003', 'Les objectifs pédagogiques étaient-ils clairs ?'),
('management', 'evaluation_question', 'MGMT_EVAL_004', 'Le formateur a-t-il su s''adapter à votre niveau ?'),
('management', 'evaluation_question', 'MGMT_EVAL_005', 'Quels points amélioreriez-vous ?'),
('management', 'evaluation_question', 'MGMT_EVAL_006', 'Étude de cas managériale évaluée par le formateur (résolution de conflit, plan de délégation).'),
('management', 'evaluation_question', 'MGMT_EVAL_007', 'Jeu de rôle : simulation d''entretien annuel ou de recadrage, évaluée par le formateur.'),
('management', 'evaluation_question', 'MGMT_EVAL_008', 'Évaluation du plan d''action managérial à 90 jours produit par l''apprenant.'),
('management', 'exercise', 'MGMT_EX_001', 'Autodiagnostic de son style de management dominant à partir d''une grille de situations.'),
('management', 'exercise', 'MGMT_EX_002', 'Jeu de rôle : déléguer une mission à un collaborateur selon son niveau d''autonomie.'),
('management', 'exercise', 'MGMT_EX_003', 'Étude de cas : identifier et désamorcer un conflit d''équipe.'),
('management', 'exercise', 'MGMT_EX_004', 'Simulation d''entretien annuel d''évaluation entre pairs, débriefée par le formateur.'),
('management', 'exercise', 'MGMT_EX_005', 'Simulation d''entretien professionnel avec grille d''évaluation légale.'),
('management', 'exercise', 'MGMT_EX_006', 'Atelier de fixation d''objectifs SMART pour une équipe fictive.'),
('management', 'exercise', 'MGMT_EX_007', 'Construction d''un tableau de bord de suivi de la performance d''équipe (indicateurs, fréquence, seuils d''alerte).'),
('management', 'exercise', 'MGMT_EX_008', 'Simulation de réunion d''équipe animée par l''apprenant devant le groupe.'),
('management', 'exercise', 'MGMT_EX_009', 'Atelier plan d''accompagnement au changement pour un projet donné (parties prenantes, résistances, plan de communication).'),
('management', 'exercise', 'MGMT_EX_010', 'Étude de cas : construire un plan de cohésion d''équipe (team building) adapté à un budget et un contexte donnés.'),
('management', 'exercise', 'MGMT_EX_011', 'Atelier feedback : formuler un feedback constructif à partir de mises en situation filmées ou jouées.'),
('management', 'exercise', 'MGMT_EX_012', 'Simulation de management d''équipe à distance via un outil collaboratif (visioconférence, tableau partagé).'),
('management', 'exercise', 'MGMT_EX_013', 'Construction d''un parcours d''intégration pour un nouveau collaborateur (checklist, jalons J1/J30/J90).'),
('management', 'method', 'MGMT_METHOD_001', 'Alternance d''apports théoriques, mises en situation, jeux de rôle et études de cas managériales.'),
('management', 'method', 'MGMT_METHOD_002', 'Supports variés : présentations interactives, grilles d''auto-diagnostic, fiches outils, vidéos pédagogiques.'),
('management', 'method', 'MGMT_METHOD_003', 'Évaluations formatives en cours de formation (mises en situation, quiz, débriefs collectifs).'),
('management', 'method', 'MGMT_METHOD_004', 'Évaluation sommative en fin de parcours (étude de cas, plan d''action managérial, quiz final).'),
('management', 'method', 'MGMT_METHOD_005', 'Positionnement à l''entrée via questionnaire d''autodiagnostic managérial et entretien avec le formateur.'),
('management', 'method', 'MGMT_METHOD_006', 'Modalité hybride combinant présentiel et classe virtuelle avec outils collaboratifs de suivi d''équipe.'),
('management', 'need_example', 'MGMT_NEED_001', 'Prendre son premier poste de manager et sécuriser sa légitimité auprès de l''équipe.'),
('management', 'need_example', 'MGMT_NEED_002', 'Améliorer la gestion des conflits récurrents au sein d''une équipe déjà expérimentée.'),
('management', 'need_example', 'MGMT_NEED_003', 'Structurer les entretiens annuels et professionnels dans une structure qui n''en a jamais formalisés.'),
