('management', 'R025 - Variante longue généraliste', 'Public généraliste/particuliers avec durée longue : couverture complète des grands blocs du management.', '{"all": [{"variable": "training_duration", "operator": "greater_than_or_equal", "value": 28}, {"variable": "public_type", "operator": "in", "value": ["generaliste", "particuliers"]}]}'::jsonb, '[{"type": "add_module", "code": "MGMT_MODULE_LEADERSHIP_DECISION"}, {"type": "add_module", "code": "MGMT_MODULE_DELEGATION_TEMPS"}, {"type": "add_module", "code": "MGMT_MODULE_CONFLITS_COMM"}, {"type": "add_module", "code": "MGMT_MODULE_ANIMATION_COHESION"}, {"type": "add_module", "code": "MGMT_MODULE_ENTRETIENS_PERF"}, {"type": "add_module", "code": "MGMT_MODULE_MOTIVATION_FEEDBACK"}, {"type": "set_variable", "key": "mgmt_variant", "value": "standard_28h"}]'::jsonb, 10),
