('management', 'R028 - Profil entrepreneur encadrant une équipe', NULL, '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "entrepreneur_manager"}]}'::jsonb, '[{"type": "add_content_block", "code": "MGMT_NEED_006"}]'::jsonb, 0),
('management', 'R029 - Secteur commerce / vente', 'Marque une priorité de contenu commerce/vente sans dupliquer de contenu (les objectifs de gestion de la performance et de motivation d''équipe couvrent déjà ce contexte).', '{"all": [{"variable": "sector", "operator": "equals", "value": "commerce_vente"}]}'::jsonb, '[{"type": "set_variable", "key": "mgmt_sector_focus", "value": "commerce"}]'::jsonb, 0),
