insert into content_blocks (category_id, type, code, text) values
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_001', 'Comprendre les fondamentaux du marketing digital et les leviers d''acquisition, de conversion et de fidélisation.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_002', 'Élaborer une stratégie marketing digital cohérente avec les objectifs, la cible et le budget de l''entreprise.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_003', 'Optimiser la structure et le contenu d''un site pour le référencement naturel (SEO on-page) et réaliser un audit technique.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_004', 'Construire une stratégie de mots-clés, un maillage interne et une stratégie de netlinking pour renforcer l''autorité d''un site.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_005', 'Créer et paramétrer une campagne Google Ads (Search, Display, Shopping).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_006', 'Définir une stratégie d''enchères et un budget adaptés, et rédiger des annonces publicitaires performantes.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_007', 'Concevoir et automatiser une séquence d''emails marketing segmentée et personnalisée (bienvenue, nurturing, relance panier).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_008', 'Mettre en place un scénario de marketing automation déclenché par le comportement utilisateur et qualifier les prospects par lead scoring.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_009', 'Construire une stratégie inbound marketing et générer des leads qualifiés via un lead magnet et une landing page.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_010', 'Élaborer une ligne éditoriale et rédiger des contenus web optimisés (articles, livres blancs, newsletters).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_011', 'Construire une identité de marque digitale cohérente (positionnement, ton, univers visuel).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_012', 'Mettre en œuvre des expérimentations growth hacking (tests A/B, itérations rapides) pour identifier des leviers d''acquisition à faible coût.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_013', 'Paramétrer un outil d''analyse web (Google Analytics 4), suivre les objectifs de conversion et construire un tableau de bord de pilotage.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_014', 'Cartographier un tunnel de conversion (funnel AARRR) et réduire les points de friction et le taux d''abandon.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_015', 'Définir ses personas et adapter son message marketing à chaque segment de cible.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_016', 'Construire un plan marketing digital structuré (objectifs, cibles, canaux, calendrier, budget).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_017', 'Construire et suivre un budget marketing digital par canal, et calculer le ROI, le CAC et la LTV.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_018', 'Mettre en place un programme d''affiliation adapté à son activité et à ses partenaires.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_019', 'Développer sa présence et ses ventes sur une marketplace (Amazon, Cdiscount, etc.).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_020', 'Créer et optimiser une boutique e-commerce (catalogue, fiches produits, tunnel d''achat, paiement).'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_021', 'Appliquer les principes d''ergonomie et d''expérience utilisateur (UX/UI) à un site web ou une boutique en ligne.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_022', 'Mettre en place une campagne de retargeting/remarketing pour relancer les visiteurs et prospects non convertis.'),
('marketing_digital', 'pedagogical_objective', 'MKT_OBJ_023', 'Réaliser une veille concurrentielle digitale et en tirer des axes d''amélioration pour sa stratégie.'),
('marketing_digital', 'skill', 'MKT_SKILL_001', 'Élaboration et pilotage d''une stratégie marketing digital.'),
('marketing_digital', 'skill', 'MKT_SKILL_002', 'Maîtrise des techniques de référencement naturel (SEO on-page et off-page).'),
('marketing_digital', 'skill', 'MKT_SKILL_003', 'Paramétrage et pilotage de campagnes Google Ads (SEA).'),
('marketing_digital', 'skill', 'MKT_SKILL_004', 'Utilisation d''un outil d''email automation (Mailchimp, Brevo, ActiveCampaign).'),
('marketing_digital', 'skill', 'MKT_SKILL_005', 'Analyse de données avec Google Analytics 4 et construction de tableaux de bord.'),
('marketing_digital', 'skill', 'MKT_SKILL_006', 'Paramétrage d''une boutique en ligne (CMS e-commerce : WooCommerce, Shopify, PrestaShop).'),
('marketing_digital', 'positioning_question', 'MKT_POS_001', 'Quelle formation souhaitez-vous suivre ?'),
('marketing_digital', 'positioning_question', 'MKT_POS_002', 'Quelle est votre situation professionnelle actuelle ? (Salarié·e / Entrepreneur / Demandeur d''emploi / Particulier)'),
('marketing_digital', 'positioning_question', 'MKT_POS_003', 'Quel est votre secteur d''activité ?'),
('marketing_digital', 'positioning_question', 'MKT_POS_004', 'Quel est votre niveau initial en marketing digital ? (Débutant / Intermédiaire / Avancé)'),
('marketing_digital', 'positioning_question', 'MKT_POS_005', 'Quelles sont vos attentes ? (Développer des compétences / Obtenir une certification / Autre)'),
('marketing_digital', 'positioning_question', 'MKT_POS_006', 'Quels sont vos objectifs concrets pour cette formation ?'),
('marketing_digital', 'positioning_question', 'MKT_POS_007', 'Quels outils/canaux marketing digital utilisez-vous déjà ? (SEO / SEA / Emailing / Réseaux sociaux / Aucun)'),
('marketing_digital', 'positioning_question', 'MKT_POS_008', 'Avez-vous déjà suivi une formation sur ce sujet ? Si oui, laquelle ?'),
('marketing_digital', 'positioning_question', 'MKT_POS_009', 'Quelle modalité préférez-vous ? (Présentiel / Distanciel / Hybride)'),
('marketing_digital', 'positioning_question', 'MKT_POS_010', 'Avez-vous des besoins spécifiques (santé, handicap) à signaler ?'),
('marketing_digital', 'positioning_question', 'MKT_POS_011', 'Réalisation d''un audit / diagnostic marketing digital de l''activité existante (site, présence en ligne, canaux utilisés).'),
('marketing_digital', 'positioning_question', 'MKT_POS_012', 'Quel est votre objectif prioritaire ? (Générer du trafic / Générer des leads / Vendre en ligne / Développer sa marque)'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_001', 'Quiz final Marketing Digital en ligne (QCM), seuil de réussite : 70 %.'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_002', 'La formation a-t-elle répondu à vos attentes ? (Oui / Partiellement / Non)'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_003', 'Les objectifs pédagogiques étaient-ils clairs ?'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_004', 'Le formateur a-t-il su s''adapter à votre niveau ?'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_005', 'Quels points amélioreriez-vous ?'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_006', 'Étude de cas / production réelle (plan marketing digital, campagne) évaluée par le formateur.'),
('marketing_digital', 'evaluation_question', 'MKT_EVAL_007', 'Évaluation de la campagne SEA ou du tunnel de conversion optimisé produit par l''apprenant en atelier.'),
('marketing_digital', 'exercise', 'MKT_EX_001', 'Réaliser un audit marketing digital d''une entreprise (site, SEO, présence en ligne) et construire un plan d''action.'),
('marketing_digital', 'exercise', 'MKT_EX_002', 'Construire un plan marketing digital complet (objectifs, personas, canaux, budget, calendrier).'),
('marketing_digital', 'exercise', 'MKT_EX_003', 'Réaliser un audit SEO technique et construire une stratégie de mots-clés et de netlinking.'),
('marketing_digital', 'exercise', 'MKT_EX_004', 'Paramétrer une campagne Google Ads Search de A à Z (mots-clés, annonces, budget, enchères).'),
('marketing_digital', 'exercise', 'MKT_EX_005', 'Concevoir une séquence email automation segmentée (bienvenue, nurturing, relance panier).'),
('marketing_digital', 'exercise', 'MKT_EX_006', 'Créer un lead magnet et une landing page pour une stratégie inbound marketing.'),
('marketing_digital', 'exercise', 'MKT_EX_007', 'Élaborer un calendrier éditorial de contenu marketing multicanal et rédiger un article optimisé SEO.'),
('marketing_digital', 'exercise', 'MKT_EX_008', 'Paramétrer Google Analytics 4, cartographier un tunnel de conversion et proposer des optimisations.'),
('marketing_digital', 'exercise', 'MKT_EX_009', 'Calculer le ROI, le CAC et la LTV d''une campagne à partir de données chiffrées.'),
('marketing_digital', 'exercise', 'MKT_EX_010', 'Paramétrer une fiche produit, un tunnel d''achat et une campagne de retargeting sur une boutique e-commerce.'),
('marketing_digital', 'method', 'MKT_METHOD_001', 'Alternance d''apports théoriques, cas pratiques, mises en situation et ateliers collaboratifs.'),
('marketing_digital', 'method', 'MKT_METHOD_002', 'Supports variés : présentations interactives, vidéos pédagogiques, exercices en ligne, quiz, études de cas réels.'),
('marketing_digital', 'method', 'MKT_METHOD_003', 'Évaluations formatives en cours de formation (quiz, exercices pratiques).'),
('marketing_digital', 'method', 'MKT_METHOD_004', 'Évaluation sommative en fin de parcours (étude de cas, test, certification interne).'),
('marketing_digital', 'method', 'MKT_METHOD_005', 'Positionnement à l''entrée via entretien diagnostic / audit marketing digital de l''activité existante.'),
('marketing_digital', 'method', 'MKT_METHOD_006', 'Modalité hybride combinant présentiel et classe virtuelle avec outils collaboratifs.'),
('marketing_digital', 'need_example', 'MKT_NEED_001', 'Développer la visibilité d''un site internet dans les moteurs de recherche (SEO).'),
('marketing_digital', 'need_example', 'MKT_NEED_002', 'Générer des leads qualifiés et augmenter le taux de conversion du site.'),
('marketing_digital', 'need_example', 'MKT_NEED_003', 'Vendre en ligne et développer une activité e-commerce.'),
('marketing_digital', 'need_example', 'MKT_NEED_004', 'Automatiser la relation client (emailing, scénarios de nurturing) pour gagner du temps.'),
('marketing_digital', 'need_example', 'MKT_NEED_005', 'Construire une stratégie marketing digital cohérente avant de se lancer (entrepreneuriat / reconversion).'),
('marketing_digital', 'need_example', 'MKT_NEED_006', 'Piloter et justifier le budget marketing digital auprès de sa direction (ROI, KPI).');
