('marketing_digital', 'R024 - Profil entrepreneur / reconversion', 'Priorise le besoin de construire une stratégie marketing digital cohérente avant de se lancer pour un public en création d''activité ou en reconversion.', '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "freelance_entrepreneur"}]}'::jsonb, '[{"type": "add_content_block", "code": "MKT_NEED_005"}]'::jsonb, 0),
('marketing_digital', 'R025 - Niveau débutant : priorité aux fondamentaux', 'Priorise les blocs fondamentaux déjà ajoutés par les autres règles — ne crée pas de nouveau contenu, ajuste la priorité d''affichage.', '{"all": [{"variable": "entry_level", "operator": "equals", "value": "debutant"}]}'::jsonb, '[{"type": "set_variable", "key": "mkt_priority_focus", "value": "fondamentaux"}]'::jsonb, 0);
insert into content_blocks (category_id, type, code, text) values
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_001', 'Élaborer une stratégie de sourcing multicanal (jobboards, réseaux sociaux, cooptation, CVthèques) adaptée au poste à pourvoir.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_002', 'Rédiger une offre d''emploi attractive et non discriminatoire, conforme aux exigences légales.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_003', 'Conduire un entretien d''embauche structuré à l''aide d''une grille d''évaluation objective des compétences, en évitant les biais de recrutement.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_004', 'Construire un parcours d''intégration (onboarding) formalisé pour un nouveau collaborateur, incluant livret d''accueil et entretiens à 30/60/90 jours.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_005', 'Constituer et tenir à jour un dossier administratif du salarié et gérer les formalités d''embauche (DPAE, contrat de travail, registre du personnel, visite médicale).'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_006', 'Identifier les fondamentaux du droit du travail applicables à la gestion quotidienne du personnel et distinguer les différents types de contrats de travail (CDI, CDD, intérim, alternance).'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_007', 'Comprendre les mécanismes de calcul d''un bulletin de paie (brut, net, cotisations sociales) et les obligations déclaratives liées à la paie (DSN).'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_008', 'Mettre en place une démarche de gestion prévisionnelle des emplois et des compétences (GPEC) et réaliser une cartographie des emplois pour identifier les écarts à combler.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_009', 'Construire un plan de développement des compétences et mobiliser les dispositifs de financement de la formation professionnelle (OPCO, CPF).'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_010', 'Mettre en œuvre une démarche de gestion des talents, de détection des potentiels et de plans de succession / mobilité interne.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_011', 'Définir et déployer une stratégie de marque employeur cohérente pour attirer et fidéliser les candidats.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_012', 'Conduire un entretien professionnel et un entretien annuel d''évaluation conformes aux obligations légales.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_013', 'Utiliser un système d''information RH (SIRH) pour piloter les processus RH (recrutement, paie, formation, congés).'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_014', 'Mettre en œuvre une démarche de qualité de vie et des conditions de travail (QVCT) et prévenir les risques psychosociaux.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_015', 'Identifier les sources de conflits en entreprise et mobiliser des techniques de médiation et de résolution.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_016', 'Sécuriser les procédures de rupture du contrat de travail (démission, licenciement, rupture conventionnelle).'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_017', 'Mettre en place une politique de diversité et d''inclusion et prévenir les discriminations en entreprise.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_018', 'Concevoir une politique de rémunération et d''avantages sociaux motivante et équitable.'),
('ressources_humaines', 'pedagogical_objective', 'RH_OBJ_019', 'Élaborer un plan de communication RH interne pour informer et engager les collaborateurs.'),
('ressources_humaines', 'skill', 'RH_SKILL_001', 'Conduite d''entretien de recrutement structuré.'),
('ressources_humaines', 'skill', 'RH_SKILL_002', 'Maîtrise des fondamentaux du droit du travail appliqué à la gestion du personnel.'),
('ressources_humaines', 'skill', 'RH_SKILL_003', 'Lecture et élaboration d''un bulletin de paie.'),
('ressources_humaines', 'skill', 'RH_SKILL_004', 'Utilisation d''un système d''information RH (SIRH).'),
('ressources_humaines', 'skill', 'RH_SKILL_005', 'Conduite d''entretiens professionnels et d''évaluation.'),
('ressources_humaines', 'skill', 'RH_SKILL_006', 'Médiation et gestion des conflits en entreprise.'),
('ressources_humaines', 'skill', 'RH_SKILL_007', 'Élaboration d''une cartographie des emplois et des compétences (GPEC).'),
('ressources_humaines', 'positioning_question', 'RH_POS_001', 'Quelle formation souhaitez-vous suivre ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_002', 'Quelle est votre situation professionnelle actuelle ? (Salarié·e / Entrepreneur / Demandeur d''emploi / Particulier)'),
('ressources_humaines', 'positioning_question', 'RH_POS_003', 'Quel est votre secteur d''activité ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_004', 'Quelle est votre fonction actuelle en lien avec les ressources humaines (assistant RH, chargé de recrutement, manager, dirigeant, autre) ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_005', 'Quel est votre niveau initial sur le sujet ? (Débutant / Intermédiaire / Avancé)'),
('ressources_humaines', 'positioning_question', 'RH_POS_006', 'Quelles sont vos attentes ? (Développer des compétences / Obtenir une certification / Autre)'),
('ressources_humaines', 'positioning_question', 'RH_POS_007', 'Quels sont vos objectifs concrets pour cette formation ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_008', 'Combien de salariés compte votre structure (ou celle pour laquelle vous intervenez) ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_009', 'Avez-vous déjà suivi une formation RH ? Si oui, laquelle ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_010', 'Quelle modalité préférez-vous ? (Présentiel / Distanciel / Hybride)'),
('ressources_humaines', 'positioning_question', 'RH_POS_011', 'Avez-vous des besoins spécifiques (santé, handicap) à signaler ?'),
('ressources_humaines', 'positioning_question', 'RH_POS_012', 'Souhaitez-vous être mis en contact avec le référent handicap ?'),
('ressources_humaines', 'evaluation_question', 'RH_EVAL_001', 'Quiz final Ressources humaines en ligne (QCM), seuil de réussite : 70 %.'),
('ressources_humaines', 'evaluation_question', 'RH_EVAL_002', 'La formation a-t-elle répondu à vos attentes ? (Oui / Partiellement / Non)'),
('ressources_humaines', 'evaluation_question', 'RH_EVAL_003', 'Les objectifs pédagogiques étaient-ils clairs ?'),
('ressources_humaines', 'evaluation_question', 'RH_EVAL_004', 'Le formateur a-t-il su s''adapter à votre niveau ?'),
('ressources_humaines', 'evaluation_question', 'RH_EVAL_005', 'Étude de cas : traitement complet d''un dossier de recrutement (offre, grille d''entretien, décision) évalué par le formateur.'),
('ressources_humaines', 'evaluation_question', 'RH_EVAL_006', 'Jeu de rôle : simulation d''un entretien annuel d''évaluation ou d''un entretien de médiation face à un conflit.'),
('ressources_humaines', 'exercise', 'RH_EX_001', 'Rédiger une offre d''emploi et définir un plan de sourcing multicanal pour un poste donné.'),
('ressources_humaines', 'exercise', 'RH_EX_002', 'Simuler un entretien d''embauche à partir d''une grille d''évaluation des compétences (jeu de rôle en binôme).'),
('ressources_humaines', 'exercise', 'RH_EX_003', 'Construire un parcours d''intégration et un livret d''accueil pour un nouveau salarié.'),
('ressources_humaines', 'exercise', 'RH_EX_004', 'Constituer un dossier administratif complet d''embauche (DPAE, contrat, registre du personnel) à partir d''un cas pratique.'),
('ressources_humaines', 'exercise', 'RH_EX_005', 'Étude de cas : qualifier un contrat de travail et identifier les clauses obligatoires et facultatives.'),
('ressources_humaines', 'exercise', 'RH_EX_006', 'Décoder un bulletin de paie et calculer le salaire net à partir du salaire brut (cas pratique chiffré).'),
('ressources_humaines', 'exercise', 'RH_EX_007', 'Réaliser une cartographie des emplois et des compétences pour un service donné et identifier les écarts.'),
('ressources_humaines', 'exercise', 'RH_EX_008', 'Construire un plan de développement des compétences et identifier les dispositifs de financement mobilisables.'),
('ressources_humaines', 'exercise', 'RH_EX_009', 'Élaborer une grille de détection des potentiels et un plan de mobilité interne.'),
('ressources_humaines', 'exercise', 'RH_EX_010', 'Simuler la conduite d''un entretien professionnel et d''un entretien annuel d''évaluation.'),
('ressources_humaines', 'exercise', 'RH_EX_011', 'Prise en main guidée d''un SIRH : création d''une fiche salarié, suivi des congés et des formations.'),
('ressources_humaines', 'exercise', 'RH_EX_012', 'Élaborer un plan d''action QVCT à partir d''un diagnostic de risques psychosociaux (étude de cas).'),
('ressources_humaines', 'exercise', 'RH_EX_013', 'Jeu de rôle : médiation d''un conflit entre deux collaborateurs ou entre un salarié et son manager.'),
('ressources_humaines', 'exercise', 'RH_EX_014', 'Étude de cas : sécuriser une procédure de licenciement ou de rupture conventionnelle étape par étape.'),
('ressources_humaines', 'exercise', 'RH_EX_015', 'Analyser une situation de discrimination potentielle et proposer un plan d''action diversité/inclusion.'),
('ressources_humaines', 'method', 'RH_METHOD_001', 'Alternance d''apports théoriques, études de cas, mises en situation et ateliers pratiques.'),
('ressources_humaines', 'method', 'RH_METHOD_002', 'Supports variés : présentations interactives, fiches pratiques, modèles de documents RH, quiz, études de cas réels.'),
('ressources_humaines', 'method', 'RH_METHOD_003', 'Évaluations formatives en cours de formation (quiz, exercices pratiques, mises en situation).'),
('ressources_humaines', 'method', 'RH_METHOD_004', 'Évaluation sommative en fin de parcours (étude de cas, test, certification interne).'),
('ressources_humaines', 'method', 'RH_METHOD_005', 'Positionnement à l''entrée via questionnaire diagnostic des connaissances et pratiques RH du participant.'),
('ressources_humaines', 'method', 'RH_METHOD_006', 'Modalité hybride combinant présentiel et classe virtuelle avec outils collaboratifs et partage de documents RH.'),
('ressources_humaines', 'need_example', 'RH_NEED_001', 'Structurer le service RH d''une entreprise en forte croissance (recrutement massif, intégration, administration du personnel).'),
('ressources_humaines', 'need_example', 'RH_NEED_002', 'Sécuriser juridiquement les pratiques RH d''un dirigeant de TPE/PME qui gère seul son personnel.'),
('ressources_humaines', 'need_example', 'RH_NEED_003', 'Monter en compétences pour évoluer d''un poste administratif vers un poste d''assistant RH généraliste.'),
('ressources_humaines', 'need_example', 'RH_NEED_004', 'Mettre en place les outils et process RH lors de la création d''un nouvel organisme ou d''une nouvelle structure.'),
('ressources_humaines', 'need_example', 'RH_NEED_005', 'Améliorer le climat social et prévenir les risques psychosociaux au sein d''une équipe.');
