('ressources_humaines', 'R020 - Modalité hybride', NULL, '{"all": [{"variable": "training_method", "operator": "equals", "value": "hybride"}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_METHOD_006"}]'::jsonb, 0),
('ressources_humaines', 'R021 - Variante compacte TPE/PME (dirigeant gérant seul son personnel)', 'Une durée courte ou un public dirigeant/entrepreneur oriente vers un socle RH opérationnel prioritaire (administratif, droit du travail, paie), au détriment des modules stratégiques (GPEC, marque employeur) sauf choix explicite.', '{"any": [{"variable": "training_duration", "operator": "less_than_or_equal", "value": 14}, {"variable": "public_type", "operator": "in", "value": ["entrepreneurs", "dirigeant"]}]}'::jsonb, '[{"type": "add_module", "code": "RH_MODULE_GESTION_ADMINISTRATIVE"}, {"type": "add_module", "code": "RH_MODULE_DROIT_TRAVAIL"}, {"type": "add_module", "code": "RH_MODULE_PAIE"}, {"type": "set_variable", "key": "rh_variant", "value": "tpe_pme_compacte"}, {"type": "remove_module", "code": "RH_MODULE_GPEC_COMPETENCES"}, {"type": "remove_module", "code": "RH_MODULE_TALENTS_MARQUE_COMM"}]'::jsonb, 10),
('ressources_humaines', 'R022 - Variante généraliste complète (grande structure)', 'Durée longue et public salariés/entreprise : couverture RH généraliste complète, du recrutement à la gestion des talents.', '{"all": [{"variable": "training_duration", "operator": "greater_than_or_equal", "value": 35}, {"variable": "public_type", "operator": "in", "value": ["salaries", "entreprise"]}]}'::jsonb, '[{"type": "add_module", "code": "RH_MODULE_RECRUTEMENT_SOURCING"}, {"type": "add_module", "code": "RH_MODULE_ENTRETIEN_INTEGRATION"}, {"type": "add_module", "code": "RH_MODULE_GPEC_COMPETENCES"}, {"type": "add_module", "code": "RH_MODULE_TALENTS_MARQUE_COMM"}, {"type": "add_module", "code": "RH_MODULE_QVCT_DIVERSITE"}, {"type": "add_content_block", "code": "RH_NEED_001"}, {"type": "set_variable", "key": "rh_variant", "value": "generaliste_complet"}]'::jsonb, 10),
('ressources_humaines', 'R023 - Niveau débutant', 'Priorise les blocs fondamentaux (administratif, droit du travail, paie) déjà ajoutés par les autres règles — ne crée pas de nouveau contenu, ajuste la priorité d''affichage.', '{"all": [{"variable": "entry_level", "operator": "equals", "value": "debutant"}]}'::jsonb, '[{"type": "set_variable", "key": "rh_priority_focus", "value": "fondamentaux"}]'::jsonb, 0),
('ressources_humaines', 'R024 - Niveau avancé', NULL, '{"all": [{"variable": "entry_level", "operator": "equals", "value": "avance"}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_OBJ_010"}]'::jsonb, 0),
('ressources_humaines', 'R025 - Profil dirigeant de TPE/PME gérant seul son personnel', 'Priorise la sécurisation juridique des pratiques RH pour un dirigeant qui cumule la fonction RH avec son activité principale.', '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "dirigeant_tpe"}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_NEED_002"}]'::jsonb, 0),
('ressources_humaines', 'R026 - Profil en évolution vers un poste RH généraliste', NULL, '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "evolution_poste"}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_NEED_003"}]'::jsonb, 0),
('ressources_humaines', 'R027 - Profil création d''organisme / nouvelle structure', NULL, '{"all": [{"variable": "beneficiary_profile", "operator": "equals", "value": "creation_structure"}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_NEED_004"}]'::jsonb, 0),
('ressources_humaines', 'R028 - Module QVCT/diversité activé par la veille RPS', 'Illustration du mécanisme veille → règle : ce module est renforcé suite à une fiche de veille sociale/juridique validée en back-office (hausse des obligations de prévention des risques psychosociaux), indépendamment de la variante choisie.', '{"all": [{"variable": "admin_flag_veille_rps", "operator": "is_true", "value": true}]}'::jsonb, '[{"type": "add_module", "code": "RH_MODULE_QVCT_DIVERSITE"}]'::jsonb, 5),
('ressources_humaines', 'R029 - Secteur à climat social sensible (santé, industrie)', 'Ces secteurs présentent un absentéisme et des tensions sociales plus marqués, justifiant l''ajout d''un exemple de besoin ciblé sur le climat social.', '{"all": [{"variable": "sector", "operator": "in", "value": ["sante", "industrie"]}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_NEED_005"}]'::jsonb, 0),
('ressources_humaines', 'R030 - Public managers', 'Les managers sont en première ligne sur l''entretien annuel et la gestion des tensions d''équipe : renforcement ciblé sur ces deux compétences.', '{"all": [{"variable": "public_type", "operator": "equals", "value": "managers"}]}'::jsonb, '[{"type": "add_content_block", "code": "RH_OBJ_012"}, {"type": "add_content_block", "code": "RH_SKILL_006"}, {"type": "add_module", "code": "RH_MODULE_ENTRETIENS_PRO_SIRH"}]'::jsonb, 0);
insert into content_blocks (category_id, type, code, text) values
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_001', 'Maîtriser les fondamentaux du cycle de vente, de la prise de contact à la conclusion.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_002', 'Adopter une posture commerciale professionnelle adaptée à son secteur d''activité.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_003', 'Construire un plan de prospection commerciale multicanal (terrain, téléphone, réseaux, recommandation).'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_004', 'Qualifier un fichier prospects et prioriser les cibles selon leur potentiel (méthode ABC).'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_005', 'Conduire un entretien de prospection téléphonique et obtenir un rendez-vous qualifié.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_006', 'Franchir les barrages téléphoniques et gérer le refus au téléphone avec professionnalisme.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_007', 'Préparer et conduire un rendez-vous commercial structuré, de l''ouverture à la prise de congé.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_008', 'Découvrir les besoins explicites et implicites du client par un questionnement structuré (méthode SPIN ou entonnoir).'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_009', 'Construire un argumentaire de vente selon la méthode CAP (Caractéristique-Avantage-Preuve).'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_010', 'Adapter son argumentaire aux typologies de clients selon la méthode SONCAS.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_011', 'Répondre aux objections courantes avec la méthode CRAC (Creuser-Reformuler-Argumenter-Contrôler).'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_012', 'Identifier les signaux d''achat verbaux et non verbaux chez le client.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_013', 'Utiliser différentes techniques de closing adaptées à la situation de vente.'),
('vente_commerce', 'pedagogical_objective', 'VENTE_OBJ_014', 'Conduire une négociation commerciale en préservant sa marge et la relation client.'),
