('vente_commerce', 'R023 - Variante longue généraliste (durée ≥ 35h, public particuliers/généraliste)', 'Public généraliste/particuliers avec durée longue : couverture complète du cycle de vente, de la prospection à la négociation.', '{"all": [{"variable": "training_duration", "operator": "greater_than_or_equal", "value": 35}, {"variable": "public_type", "operator": "in", "value": ["generaliste", "particuliers"]}]}'::jsonb, '[{"type": "add_module", "code": "VENTE_MODULE_FONDAMENTAUX"}, {"type": "add_module", "code": "VENTE_MODULE_PROSPECTION"}, {"type": "add_module", "code": "VENTE_MODULE_ARGUMENTATION"}, {"type": "add_module", "code": "VENTE_MODULE_OBJECTIONS_CLOSING"}, {"type": "add_module", "code": "VENTE_MODULE_NEGOCIATION"}, {"type": "set_variable", "key": "vente_variant", "value": "standard_5j"}]'::jsonb, 10),
('vente_commerce', 'R024 - Public entrepreneurs / freelances', 'Priorise un contenu adapté à un commercial qui gère seul l''intégralité de son cycle de vente.', '{"all": [{"variable": "public_type", "operator": "in", "value": ["entrepreneurs", "freelance"]}]}'::jsonb, '[{"type": "add_content_block", "code": "VENTE_NEED_001"}, {"type": "add_content_block", "code": "VENTE_NEED_002"}]'::jsonb, 0),
('vente_commerce', 'R025 - Public en reconversion vers la vente', 'Priorise les fondamentaux et la reprise de confiance pour un public en reconversion ou demandeur d''emploi.', '{"all": [{"variable": "public_type", "operator": "in", "value": ["demandeurs_emploi", "reconversion"]}]}'::jsonb, '[{"type": "add_content_block", "code": "VENTE_NEED_003"}, {"type": "add_content_block", "code": "VENTE_NEED_005"}]'::jsonb, 0),
('vente_commerce', 'R026 - Secteur immobilier', 'Remplace un exercice générique par un cas pratique sectoriel immobilier.', '{"all": [{"variable": "sector", "operator": "equals", "value": "immobilier"}]}'::jsonb, '[{"type": "add_content_block", "code": "VENTE_EX_016"}]'::jsonb, 0),
('vente_commerce', 'R027 - Niveau débutant', 'Priorise les blocs fondamentaux déjà ajoutés par les autres règles : ne crée pas de nouveau contenu, ajuste la priorité d''affichage.', '{"all": [{"variable": "entry_level", "operator": "equals", "value": "debutant"}]}'::jsonb, '[{"type": "set_variable", "key": "vente_priority_focus", "value": "fondamentaux"}]'::jsonb, 0),
('vente_commerce', 'R028 - Niveau avancé', NULL, '{"all": [{"variable": "entry_level", "operator": "equals", "value": "avance"}]}'::jsonb, '[{"type": "add_content_block", "code": "VENTE_OBJ_026"}]'::jsonb, 0),
('vente_commerce', 'R029 - Modalité distancielle', NULL, '{"all": [{"variable": "training_method", "operator": "equals", "value": "distanciel"}]}'::jsonb, '[{"type": "add_content_block", "code": "VENTE_METHOD_006"}, {"type": "add_module", "code": "VENTE_MODULE_DIGITAL_CRM"}]'::jsonb, 0),
('vente_commerce', 'R030 - Modalité hybride', NULL, '{"all": [{"variable": "training_method", "operator": "equals", "value": "hybride"}]}'::jsonb, '[{"type": "add_content_block", "code": "VENTE_METHOD_006"}, {"type": "add_module", "code": "VENTE_MODULE_DIGITAL_CRM"}]'::jsonb, 0);
insert into content_blocks (category_id, type, code, text) values
('web_digital', 'pedagogical_objective', 'WEB_OBJ_001', 'Comprendre le fonctionnement d''Internet et l''architecture d''un site (client/serveur, nom de domaine, hébergement).'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_002', 'Installer, configurer et structurer un site WordPress (thème, pages, menus) adapté au projet du client.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_003', 'Utiliser un constructeur de pages (Elementor ou équivalent) pour composer des mises en page sans coder.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_004', 'Créer un site vitrine de bout en bout avec un outil no-code (Wix ou Webflow) et choisir la solution adaptée au besoin du client.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_005', 'Écrire une page HTML5 sémantique, la mettre en forme avec CSS3 (Flexbox/Grid) et la publier en ligne.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_006', 'Réaliser un audit SEO on-page et définir une stratégie de mots-clés adaptée à l''activité du client.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_007', 'Optimiser la visibilité locale (fiche Google Business Profile) et suivre le trafic avec Search Console et Analytics.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_008', 'Appliquer les principes d''ergonomie (UX), réaliser un wireframe et concevoir une interface (UI) cohérente.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_009', 'Choisir un nom de domaine et un hébergement adaptés, et sécuriser le site avec un certificat SSL (DNS/HTTPS).'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_010', 'Créer une boutique en ligne (catalogue, livraison, paiement sécurisé) avec WooCommerce ou une solution no-code équivalente.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_011', 'Comprendre les obligations légales de la vente en ligne (CGV, droit de rétractation, tunnel de commande).'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_012', 'Mettre en place un plan de maintenance d''un site et diagnostiquer ses pannes courantes.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_013', 'Appliquer et vérifier les critères de base de l''accessibilité numérique (RGAA/WCAG).'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_014', 'Identifier les vulnérabilités courantes d''un site et appliquer les bonnes pratiques de sécurisation.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_015', 'Concevoir un site responsive et tester son affichage sur plusieurs terminaux et navigateurs.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_016', 'Rédiger un contenu web optimisé pour la lecture à l''écran et le référencement, et intégrer un formulaire, un paiement en ligne ou une newsletter.'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_017', 'Mesurer et améliorer la vitesse de chargement d''un site (compression d''images, mise en cache, minification).'),
('web_digital', 'pedagogical_objective', 'WEB_OBJ_018', 'Rédiger les mentions légales, la politique de confidentialité et le bandeau cookies conformément au RGPD, et décliner une identité visuelle cohérente sur le site.'),
('web_digital', 'skill', 'WEB_SKILL_001', 'Création et administration d''un site WordPress.'),
('web_digital', 'skill', 'WEB_SKILL_002', 'Prise en main d''un outil no-code (Wix ou Webflow).'),
('web_digital', 'skill', 'WEB_SKILL_003', 'Écriture de code HTML/CSS.'),
('web_digital', 'skill', 'WEB_SKILL_004', 'Diagnostic et optimisation SEO on-page.'),
('web_digital', 'skill', 'WEB_SKILL_005', 'Conception UX/UI et réalisation de maquettes.'),
('web_digital', 'skill', 'WEB_SKILL_006', 'Paramétrage d''un nom de domaine, d''un hébergement et d''un certificat SSL.'),
('web_digital', 'skill', 'WEB_SKILL_007', 'Création et sécurisation d''une boutique en ligne et maintenance technique d''un site.'),
('web_digital', 'positioning_question', 'WEB_POS_001', 'Quelle formation souhaitez-vous suivre ?'),
('web_digital', 'positioning_question', 'WEB_POS_002', 'Quelle est votre situation professionnelle actuelle ? (Salarié·e / Entrepreneur / Demandeur d''emploi / Particulier)'),
('web_digital', 'positioning_question', 'WEB_POS_003', 'Quel est votre secteur d''activité ou celui de votre projet de site internet ?'),
('web_digital', 'positioning_question', 'WEB_POS_004', 'Avez-vous déjà un site internet ? Si oui, sur quelle technologie a-t-il été créé ?'),
('web_digital', 'positioning_question', 'WEB_POS_005', 'Quel est votre niveau initial en informatique et en création de site web ? (Débutant / Intermédiaire / Avancé)'),
('web_digital', 'positioning_question', 'WEB_POS_006', 'Avez-vous déjà des notions de code (HTML, CSS) ou d''outils no-code ?'),
('web_digital', 'positioning_question', 'WEB_POS_007', 'Quel est l''objectif de votre projet de site internet ? (Vitrine / E-commerce / Portfolio / Blog / Autre)'),
('web_digital', 'positioning_question', 'WEB_POS_008', 'Quelles sont vos attentes vis-à-vis de la formation ? (Créer un site pour vous / Créer des sites pour des clients / Vous reconvertir / Autre)'),
('web_digital', 'positioning_question', 'WEB_POS_009', 'Disposez-vous déjà d''un nom de domaine ou d''un hébergement web ?'),
('web_digital', 'positioning_question', 'WEB_POS_010', 'Quelle modalité préférez-vous ? (Présentiel / Distanciel / Hybride)'),
('web_digital', 'positioning_question', 'WEB_POS_011', 'Avez-vous des besoins spécifiques (santé, handicap) à signaler ? Souhaitez-vous être mis en contact avec le référent handicap ?'),
('web_digital', 'positioning_question', 'WEB_POS_012', 'Réalisation d''un audit / entretien diagnostic du site existant et de la présence en ligne du bénéficiaire.'),
('web_digital', 'evaluation_question', 'WEB_EVAL_001', 'Quiz final Web / Création de sites en ligne (QCM), seuil de réussite : 70 %.'),
('web_digital', 'evaluation_question', 'WEB_EVAL_002', 'La formation a-t-elle répondu à vos attentes ? (Oui / Partiellement / Non)'),
('web_digital', 'evaluation_question', 'WEB_EVAL_003', 'Les objectifs pédagogiques étaient-ils clairs ?'),
('web_digital', 'evaluation_question', 'WEB_EVAL_004', 'Le formateur a-t-il su s''adapter à votre niveau ?'),
('web_digital', 'evaluation_question', 'WEB_EVAL_005', 'Quels points amélioreriez-vous ?'),
('web_digital', 'evaluation_question', 'WEB_EVAL_006', 'Mise en ligne d''un site fonctionnel réalisé par l''apprenant, évalué selon une grille critériée (structure, contenu, mise en forme).'),
('web_digital', 'evaluation_question', 'WEB_EVAL_007', 'Évaluation du livrable spécifique produit par l''apprenant selon le thème choisi (audit SEO, boutique en ligne ou plan d''optimisation de performance).'),
('web_digital', 'exercise', 'WEB_EX_001', 'Installer WordPress, choisir un thème et créer les pages principales d''un site vitrine (niveau débutant).'),
('web_digital', 'exercise', 'WEB_EX_002', 'Composer une page d''accueil avec un constructeur de pages (Elementor) à partir d''une maquette fournie.'),
('web_digital', 'exercise', 'WEB_EX_003', 'Créer un site vitrine complet avec Wix ou Webflow, de la structure à la publication.'),
('web_digital', 'exercise', 'WEB_EX_004', 'Coder une page HTML/CSS responsive à partir d''une maquette (mise en page Flexbox ou Grid).'),
('web_digital', 'exercise', 'WEB_EX_005', 'Réaliser l''audit SEO on-page d''un site existant, définir des mots-clés cibles et optimiser une fiche Google Business Profile.'),
('web_digital', 'exercise', 'WEB_EX_006', 'Réaliser un wireframe puis une maquette UI d''une page d''accueil à partir d''un brief client.'),
('web_digital', 'exercise', 'WEB_EX_007', 'Comparer trois offres d''hébergement, configurer un nom de domaine et sécuriser le site avec un certificat SSL.'),
('web_digital', 'exercise', 'WEB_EX_008', 'Créer une boutique en ligne avec WooCommerce (catalogue, livraison, paiement) et rédiger des CGV et un tunnel de commande conformes.'),
('web_digital', 'exercise', 'WEB_EX_009', 'Mettre à jour un site WordPress (thème, plugins, cœur), effectuer une sauvegarde complète et diagnostiquer une panne simulée.'),
('web_digital', 'exercise', 'WEB_EX_010', 'Auditer l''accessibilité et la sécurité d''un site existant (outil automatisé, mots de passe, mises à jour) et corriger les anomalies identifiées.'),
('web_digital', 'exercise', 'WEB_EX_011', 'Tester l''affichage d''un site sur mobile, tablette et ordinateur et corriger les problèmes de responsive design.'),
('web_digital', 'exercise', 'WEB_EX_012', 'Rédiger le contenu texte de trois pages d''un site optimisé SEO et intégrer un formulaire de contact, un module de paiement et une inscription newsletter.'),
('web_digital', 'exercise', 'WEB_EX_013', 'Rédiger les mentions légales, la politique de confidentialité et le bandeau cookies d''un site, et décliner une identité visuelle existante sur l''ensemble des pages.'),
('web_digital', 'exercise', 'WEB_EX_014', 'Atelier CV / lettre de motivation et simulation d''entretien pour un profil en reconversion vers les métiers du web (accompagnement socio-pro).'),
('web_digital', 'method', 'WEB_METHOD_001', 'Alternance d''apports théoriques, démonstrations à l''écran et mises en pratique sur un projet de site réel ou fictif.'),
('web_digital', 'method', 'WEB_METHOD_002', 'Supports variés : tutoriels pas à pas, fiches techniques, capsules vidéo, exercices guidés, études de cas.'),
('web_digital', 'method', 'WEB_METHOD_003', 'Évaluations formatives en cours de formation (quiz, exercices pratiques guidés).'),
('web_digital', 'method', 'WEB_METHOD_004', 'Évaluation sommative en fin de parcours : mise en ligne d''un site fonctionnel évalué selon une grille critériée.'),
('web_digital', 'method', 'WEB_METHOD_005', 'Positionnement à l''entrée via entretien diagnostic et audit du site existant ou du projet du bénéficiaire.'),
('web_digital', 'method', 'WEB_METHOD_006', 'Modalité hybride ou distancielle combinant présentiel, classe virtuelle et environnement de test individuel (site ou compte no-code dédié).'),
('web_digital', 'need_example', 'WEB_NEED_001', 'Créer le site vitrine de sa propre activité pour développer sa visibilité en ligne (entrepreneur).'),
('web_digital', 'need_example', 'WEB_NEED_002', 'Se reconvertir vers le métier de développeur ou d''intégrateur web (demandeur d''emploi).'),
('web_digital', 'need_example', 'WEB_NEED_003', 'Créer des sites internet pour des clients en freelance ou en agence.'),
('web_digital', 'need_example', 'WEB_NEED_004', 'Ouvrir une boutique en ligne pour vendre ses produits (artisan, commerçant).'),
('web_digital', 'need_example', 'WEB_NEED_005', 'Prendre en charge la maintenance et les mises à jour du site internet de son entreprise (salarié).'),
('web_digital', 'need_example', 'WEB_NEED_006', 'Mettre son site en conformité avec le RGPD et les règles d''accessibilité numérique.');
